function shared(key,origin){
 const role=origin==='Admin'?'Admin':origin==='Transporter'?'Transporter':'Customer';
 if(key==='messages')return shell(role,key,`${title('Conversations','Messages','Keep questions and updates linked to requests and deliveries.')}${example}<div class="card message-layout"><div class="inbox"><div class="inbox-head"><h2>Conversations</h2><div class="fields">${field('Search','Search conversations')}</div>${filters(['All','Unread'])}</div><div class="inbox-item active"><span class="avatar">E</span><div><strong>Example conversation</strong><p>About the Mercedes E-Class journey</p></div></div><div class="inbox-item"><span class="avatar">S</span><div><strong>DriveDrop support</strong><p>Account information</p></div></div></div><div class="conversation"><div class="conversation-head"><strong>Example conversation</strong><p class="tiny">Messages are connected to a request or booking.</p></div><div class="conversation-body"><div class="bubble">Hello, could you confirm the collection time?</div><div class="bubble me">I’ll confirm the time once the date is agreed.</div></div><div class="composer"><input aria-label="Message" placeholder="Write a message"><button class="btn light small" data-preview-action="Add pictures">Add pictures</button><button class="btn orange small" data-preview-action="Send message">Send</button></div></div></div><div class="workspace-block">${button('Delete conversation','danger')}</div>`);
 if(key==='notifications')return shell(role,key,`${title('Recent activity','Notifications','Review unread activity without losing the full history.',button('Mark all as read','light'))}${example}${filters(['All','Unread'])}${panel('Activity',row('New quote received','A transporter responded to an example request','18 Oct',tag('Unread','amber'),'Open','customer-requests')+row('Delivery status updated','An example booking is in transit','18 Oct',tag('Read','grey'),'Open','customer-deliveries')+`<div class="form-footer">${button('Mark as read','light')}</div>`)}`);
 if(key==='account')return shell(role,key,`${title('Account settings','Your account information','View and update the information DriveDrop holds for your account.',button('Back to dashboard','light',role.toLowerCase()+'-home'))}<div class="columns">${panel('Personal details',`<div class="detail-line"><span>Name</span><strong>Your account name</strong></div><div class="detail-line"><span>Email address</span><strong>Your login email</strong></div><div class="detail-line"><span>Account type</span><strong>${role}</strong></div>${button('Edit account details','light')}`)}${panel('Account security',`<p class="muted">Change your login email or password after the required verification.</p>${button('Change email','light')} ${button('Change password','light')}`)}</div>${role==='Transporter'?`<div class="workspace-block columns">${panel('Transporter business & documents',`<p class="muted">Business and verification details remain in the transporter account.</p>${button('Manage verification & insurance','orange','transporter-verification')} ${button('Profile photos','light','transporter-profile')}`)}${panel('Test payout details',`<p class="muted">Masked test bank details and their status appear here when set up in the Preview payout workflow.</p>${button('Update bank account','light')}`)}</div>`:''}<div class="workspace-block">${panel('Close account',`<p class="muted">Account closure follows the existing confirmation and eligibility checks.</p>${button('Close account','danger')}`)}</div>`);
 if(key==='statement')return `<main class="page-width content-page"><span class="eyebrow">Booking record</span><h1>Booking statement</h1><p class="intro">Printable statement layout. Reference, amounts and dates are supplied by the booking record.</p><div class="columns">${panel('Vehicle details',`<div class="detail-line"><span>Vehicle</span><strong>Account booking</strong></div><div class="detail-line"><span>Registration</span><strong>Booking value</strong></div>`)}${panel('Journey',`<div class="detail-line"><span>Collection</span><strong>Booking value</strong></div><div class="detail-line"><span>Delivery</span><strong>Booking value</strong></div>`)}</div><div class="workspace-block">${panel('Important dates & amounts',`<p>Existing payment, proceeds, deductions and status fields appear here without changing their calculation.</p>${button('Print statement','light')}`)}</div></main>`;
 return '';
}
function render(){
 const key=(location.hash.split('/')[1]||'home').split('?')[0];const screen=screens.find(x=>x[1]===key)||screens[0];const group=screen[0];
 let origin=sessionStorage.getItem('dd-design-origin')||'Customer';if(['Customer','Transporter','Admin'].includes(group)){origin=group;sessionStorage.setItem('dd-design-origin',group)}
 const switcher=document.getElementById('design-switcher');switcher.innerHTML=`<div><strong>DRIVEDROP · DESIGN SOURCE</strong> <small>Desktop proposal · every page uses these exact bundled assets, copy and styles</small></div><div class="switcher-right"><label for="screen-select">View page</label><select id="screen-select">${screens.map(([g,k,l])=>`<option value="${k}" ${key===k?'selected':''}>${g} / ${l}</option>`).join('')}</select><button class="btn small light" id="clean-toggle" type="button">${document.body.classList.contains('is-clean')?'Show page menu':'Hide page menu'}</button></div>`;
 document.getElementById('screen-select').onchange=e=>{location.hash='/'+e.target.value};document.getElementById('clean-toggle').onclick=()=>{document.body.classList.toggle('is-clean');render()};
 const body=group==='Public'?publicPage(key):group==='Access'?authPage(key):key==='quote'?quoteForm():group==='Customer'?customer(key):group==='Transporter'?transporter(key):group==='Admin'?admin(key):key==='terms'||key==='privacy'?publicPage(key):shared(key,origin);
 const resolved=key==='quote'?`<main class="page-width quote-page">${quoteForm()}</main>${footer()}`:body;
 const headerGroup=group==='Shared'&&!['terms','privacy'].includes(key)?origin:group;
 document.getElementById('app').innerHTML=header(headerGroup,key)+resolved;
 document.title=`${screen[2]} · DriveDrop design proposal`;
 bind();window.scrollTo(0,0);
}
function toast(message){let el=document.getElementById('preview-toast');if(!el){el=document.createElement('div');el.id='preview-toast';el.setAttribute('role','status');el.style.cssText='position:fixed;z-index:300;bottom:25px;left:50%;transform:translateX(-50%);max-width:min(450px,90vw);background:#0d2541;color:white;border-radius:10px;padding:15px 20px;box-shadow:0 12px 28px #071a3050;font:13px/1.45 ui-sans-serif,sans-serif';document.body.append(el)}el.textContent=message;clearTimeout(window.ddToastTimer);window.ddToastTimer=setTimeout(()=>el.remove(),4300)}
function bind(){
 document.querySelectorAll('[data-preview-form]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();if(form.classList.contains('search-grid'))location.hash='/quote';else toast('Design preview: submission is handled by the existing DriveDrop form after approval.')}));
 document.querySelectorAll('[data-preview-action]').forEach(btn=>btn.addEventListener('click',()=>toast(`Design preview: “${btn.dataset.previewAction}” keeps its existing DriveDrop action when implemented.`)));
 document.querySelectorAll('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{btn.parentElement.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));btn.classList.add('active')}));
 document.querySelectorAll('[data-hero-tab]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-hero-tab]').forEach(x=>x.classList.remove('active'));btn.classList.add('active');if(btn.dataset.heroTab==='deliver')location.hash='/register-transporter'}));
 document.querySelectorAll('[data-account-mode]').forEach(btn=>btn.addEventListener('click',e=>{e.preventDefault();document.querySelectorAll('[data-account-mode]').forEach(x=>x.classList.remove('active'));btn.classList.add('active');document.querySelector('.account-create').style.display=btn.dataset.accountMode==='login'?'none':''}));
 document.querySelectorAll('[data-password-toggle]').forEach(btn=>btn.addEventListener('click',()=>{const input=btn.parentElement.querySelector('input');const show=input.type==='password';input.type=show?'text':'password';btn.textContent=show?'Hide':'Show';btn.setAttribute('aria-label',`${show?'Hide':'Show'} password`)}));
 document.querySelectorAll('[data-section]').forEach(btn=>btn.addEventListener('click',()=>document.getElementById(btn.dataset.section)?.scrollIntoView({behavior:'smooth'})));
 const vehicle=document.querySelector('.quote-page .fields select');const type=[...document.querySelectorAll('.quote-page select')].find(x=>x.parentElement.querySelector('label')?.textContent==='Transport type');if(vehicle&&type){const check=()=>{let n=document.getElementById('compatibility');if(!n){n=document.createElement('p');n.id='compatibility';n.className='notice warn';type.closest('section').append(n)}n.style.display=type.value==='Enclosed transport'&&vehicle.value&&!['Car','Motorcycle','Classic / prestige'].includes(vehicle.value)?'block':'none';n.textContent='Enclosed transport is available for Car, Motorcycle and Classic / prestige. Change the vehicle or transport type to continue.'};vehicle.addEventListener('change',check);type.addEventListener('change',check)}
}
window.addEventListener('hashchange',render);render();
